<template>
  <section class="qm-discovery" :class="{ 'has-comparison': selectedNames.length > 0 }" aria-label="模型观测站">
    <header class="qm-hero"><div class="qm-hero-copy"><span class="qm-eyebrow"><i></i> GOOD QUESTIONS. GREAT MINDS.</span><h1>让每个想法，<br>遇见<span>合适的引力。</span></h1><p>文字、图像、深度思考。<br>找到擅长这一题的模型，一起往前走。</p><div class="qm-hero-stats"><span><b>{{ loading || loadError ? '—' : models.length }}</b>个模型</span><span><b>{{ loading || loadError ? '—' : readyCount }}</b>个已接入</span><a href="#qm-catalog">开始探索<ClientIcon name="arrow" /></a></div></div><div class="qm-gravity" aria-hidden="true"><span class="qm-gravity-orbit"></span><span class="qm-gravity-orbit qm-gravity-orbit-two"></span><div class="qm-prism"><i></i><i></i><i></i><b>Q</b></div><span class="qm-gravity-dot"></span><span class="qm-gravity-caption">EXPLORE YOUR NEXT POSSIBILITY</span><em>✦</em></div><span class="qm-hero-edition">QGAUSS / MODEL OBSERVATORY<br>BUILT FOR CURIOUS MINDS</span></header>
    <section id="qm-catalog" class="qm-catalog" aria-labelledby="qm-catalog-title">
      <div class="qm-heading"><div><span class="qm-eyebrow">A MIND FOR EVERY MOMENT</span><h2 id="qm-catalog-title">给这一题，选位好搭档。</h2></div><label class="qm-search"><ClientIcon name="search" /><input v-model="keyword" aria-label="搜索模型" type="search" maxlength="200" placeholder="模型、厂商、能力，都能搜" /><button v-if="keyword" type="button" aria-label="清空模型搜索" @click="keyword = ''"><ClientIcon name="close" /></button></label></div>
      <div class="qm-capabilities" aria-label="按能力筛选"><button v-for="item in capabilities" :key="item.key" type="button" :aria-pressed="capability === item.key" @click="capability = item.key"><ClientIcon :name="item.icon" />{{ item.label }}</button></div>
      <div class="qm-controls"><div class="qm-vendors" aria-label="模型厂商"><button type="button" :aria-pressed="vendor === ''" @click="vendor = ''">全部厂商</button><button v-for="item in vendors" :key="item.name" type="button" :aria-pressed="vendor === item.name" @click="vendor = item.name">{{ item.name }}<small>{{ item.count }}</small></button></div><div class="qm-view-controls"><label><input v-model="readyOnly" type="checkbox" /><span></span>只看已接入</label><select v-model="sort" aria-label="模型排序"><option value="default">默认顺序</option><option value="context">上下文从大到小</option><option value="name">名称顺序</option></select></div></div>
      <div class="qm-result-line" role="status"><span>{{ loadError ? '模型列表暂未更新' : loading ? '正在打开模型观测站…' : '找到 ' + filtered.length + ' 个模型' }}</span><button type="button" :disabled="loading || !!starting" @click="loadCatalog"><ClientIcon name="refresh" />刷新模型</button></div>
      <p v-if="startError && !detailName && !compareOpen" class="qm-inline-error" role="alert">{{ startError }}</p>
      <div v-if="loading && !models.length" class="qm-loading" role="status"><BrandLoader :size="44" text="正在校准灵感的引力…" /><div class="qm-skeletons" aria-hidden="true"><span v-for="i in 3" :key="i"></span></div></div>
      <div v-else-if="loadError" class="qm-empty" role="alert"><span>☁</span><h3>模型搭档暂时没到</h3><p>{{ loadError }}</p><button type="button" class="qgd-primary" @click="loadCatalog">再试一次<ClientIcon name="refresh" /></button></div>
      <div v-else-if="!filtered.length" class="qm-empty"><span>✳</span><h3>{{ models.length ? '换个引力方向，试试看。' : '下一位好搭档，还在准备中。' }}</h3><p>{{ models.length ? '换个关键词，或看看其他能力与厂商。' : '模型上架后，就会在这里与你相遇。' }}</p><button v-if="models.length" type="button" class="qgd-primary" @click="resetFilters">看看全部模型<ClientIcon name="arrow" /></button></div>
      <div v-else class="qm-card-grid" :aria-busy="loading"><article v-for="(model, index) in visibleModels" :key="model.name" class="qm-model-card" :class="{ 'is-offline': !model.ready }" :style="{ '--qm-order': index % 9 }"><div class="qm-card-top"><span class="qm-model-icon" :class="'qm-icon-' + iconFor(model)"><ClientIcon :name="iconFor(model)" /><i></i></span><span class="qm-readiness" :class="{ 'is-ready': model.ready }"><i></i>{{ model.ready ? '已接入' : '暂未接入' }}</span><span v-if="model.badge" class="qm-badge">{{ model.badge }}</span></div><button type="button" class="qm-card-open" :aria-label="'查看模型：' + (model.displayName || model.name)" @click="openDetail(model, $event)"><span class="qm-vendor-label">{{ modelVendor(model) }}</span><h3>{{ model.displayName || model.name }}<ClientIcon name="arrowUpRight" /></h3><code>{{ model.name }}</code><p>{{ model.description || '这位搭档还没有介绍，可以先看看能力与参数。' }}</p></button><div class="qm-tags"><span v-for="cap in modelCaps(model).slice(0, 4)" :key="cap">{{ capabilityLabel(cap) }}</span><span v-for="tag in (model.tags || []).slice(0, 2)" :key="'tag-' + tag">{{ tag }}</span></div><div class="qm-card-metrics"><div :title="exactTokens(model.maxContext)"><small>上下文窗口</small><b>{{ contextLabel(model.maxContext) }}</b></div><div><small>{{ imageOnly(model) ? '创作费用' : '当前次数规则' }}</small><strong>{{ modelBilling(model).title }}</strong></div></div><footer><button type="button" class="qm-compare-toggle" :aria-label="(selectedNames.includes(model.name) ? '移出对照：' : '加入对照：') + (model.displayName || model.name)" :aria-pressed="selectedNames.includes(model.name)" @click="toggleCompare(model)"><ClientIcon :name="selectedNames.includes(model.name) ? 'check' : 'plus'" />{{ selectedNames.includes(model.name) ? '已加入' : '对照' }}</button><button type="button" class="qm-use" :disabled="!model.ready || !!starting" :aria-label="(imageOnly(model) ? '用' : '与') + (model.displayName || model.name) + (imageOnly(model) ? '开始创作' : '开始对话')" @click="launch(model)">{{ starting === model.name ? '正在确认…' : model.ready ? modelEntry(model).label : '暂未接入' }}<ClientIcon name="arrow" /></button></footer></article></div>
      <div v-if="!loadError && filtered.length" class="qm-catalog-footer"><span>不同的能力，让想法有更多可能。</span><button v-if="visibleModels.length < filtered.length" type="button" @click="limit += 9">继续探索 <small>{{ visibleModels.length }} / {{ filtered.length }}</small><ClientIcon name="plus" /></button><span v-else>已经看到全部模型 <i>✦</i></span></div>
    </section>
    <aside v-if="selectedModels.length" class="qm-compare-tray" aria-label="模型对照栏"><div class="qm-tray-models"><span v-for="model in selectedModels" :key="model.name"><b>{{ model.displayName || model.name }}</b><button type="button" :aria-label="'移出对照：' + (model.displayName || model.name)" @click="toggleCompare(model)"><ClientIcon name="close" /></button></span></div><div class="qm-tray-actions"><small>{{ selectedModels.length }} / 3</small><button type="button" class="qm-tray-clear" @click="selectedNames = []">清空</button><button ref="compareOpener" type="button" class="qm-use" :disabled="selectedModels.length < 2" @click="openCompare">对照参数<ClientIcon name="layout" /></button></div></aside>
    <dialog ref="detailDialog" class="qm-dialog qm-detail-dialog" aria-labelledby="qm-detail-title" @cancel.prevent="closeDetail" @close="onDetailClosed" @click="onBackdrop($event, 'detail')"><template v-if="detailModel"><header><span class="qm-eyebrow">MEET YOUR NEXT MIND</span><button type="button" class="qm-dialog-close" aria-label="关闭模型详情" @click="closeDetail"><ClientIcon name="close" /></button></header><div class="qm-detail-heading"><span class="qm-model-icon" :class="'qm-icon-' + iconFor(detailModel)"><ClientIcon :name="iconFor(detailModel)" /><i></i></span><div><span class="qm-vendor-label">{{ modelVendor(detailModel) }}</span><h2 id="qm-detail-title">{{ detailModel.displayName || detailModel.name }}</h2><code>{{ detailModel.name }}</code></div><span class="qm-readiness" :class="{ 'is-ready': detailModel.ready }"><i></i>{{ detailModel.ready ? '已接入' : '暂未接入' }}</span></div><p class="qm-detail-description">{{ detailModel.description || '暂无介绍，先从模型的能力与参数了解它。' }}</p><div class="qm-tags"><span v-for="cap in modelCaps(detailModel)" :key="cap">{{ capabilityLabel(cap) }}</span><span v-for="tag in detailModel.tags || []" :key="'detail-' + tag">{{ tag }}</span></div><div class="qm-detail-specs"><div><ClientIcon name="file" /><small>上下文窗口</small><b>{{ exactTokens(detailModel.maxContext) }}</b></div><div><ClientIcon name="chat" /><small>最大输出</small><b>{{ exactTokens(detailModel.maxOutput) }}</b></div></div><section class="qm-billing-note"><ClientIcon name="wallet" /><div><small>当前站点设置</small><h3>{{ modelBilling(detailModel).title }}</h3><p>{{ modelBilling(detailModel).detail }}</p></div></section><details class="qm-cost-reference"><summary>用量成本参考<ClientIcon name="chevronRight" /></summary><dl><div><dt>输入 / 百万 tokens</dt><dd>{{ microsLabel(detailModel.priceInPerM) }}</dd></div><div><dt>输出 / 百万 tokens</dt><dd>{{ microsLabel(detailModel.priceOutPerM) }}</dd></div></dl><p>这是模型用量的成本参考，不按此金额扣钱包余额。实际次数规则见上方。</p></details><p v-if="startError" class="qm-inline-error" role="alert">{{ startError }}</p><footer class="qm-detail-actions"><button type="button" class="qm-compare-toggle" :aria-pressed="selectedNames.includes(detailModel.name)" @click="toggleCompare(detailModel)"><ClientIcon :name="selectedNames.includes(detailModel.name) ? 'check' : 'plus'" />{{ selectedNames.includes(detailModel.name) ? '已加入对照' : '加入对照' }}</button><button type="button" class="qm-use" :disabled="!detailModel.ready || !!starting" @click="launch(detailModel)">{{ starting === detailModel.name ? '正在确认…' : detailModel.ready ? modelEntry(detailModel).label : '暂未接入' }}<ClientIcon name="arrowUpRight" /></button></footer></template></dialog>
    <dialog ref="compareDialog" class="qm-dialog qm-compare-dialog" aria-labelledby="qm-compare-title" @cancel.prevent="closeCompare" @close="onCompareClosed" @click="onBackdrop($event, 'compare')"><header><div><span class="qm-eyebrow">DIFFERENT MINDS, CLEARER CHOICES</span><h2 id="qm-compare-title"><span>放在一起，</span><span>看得更清楚。</span></h2><p>对照当前模型配置，选适合这一题的能力。</p></div><button type="button" class="qm-dialog-close" aria-label="关闭模型对照" @click="closeCompare"><ClientIcon name="close" /></button></header><div class="qm-compare-grid" :style="{ '--qm-columns': selectedModels.length }"><article v-for="model in selectedModels" :key="model.name"><div class="qm-compare-model-title"><span class="qm-model-icon" :class="'qm-icon-' + iconFor(model)"><ClientIcon :name="iconFor(model)" /></span><span class="qm-vendor-label">{{ modelVendor(model) }}</span><h3>{{ model.displayName || model.name }}</h3><code>{{ model.name }}</code></div><dl><div><dt>当前状态</dt><dd class="qm-readiness" :class="{ 'is-ready': model.ready }"><i></i>{{ model.ready ? '已接入' : '暂未接入' }}</dd></div><div><dt>适用入口</dt><dd>{{ modelEntry(model).kind }}</dd></div><div><dt>上下文窗口</dt><dd>{{ exactTokens(model.maxContext) }}</dd></div><div><dt>最大输出</dt><dd>{{ exactTokens(model.maxOutput) }}</dd></div><div><dt>能力</dt><dd>{{ modelCaps(model).map(capabilityLabel).join(' · ') || '未配置' }}</dd></div><div><dt>当前次数规则</dt><dd>{{ modelBilling(model).title }}</dd></div></dl><button type="button" class="qm-use" :disabled="!model.ready || !!starting" :aria-label="'选择' + (model.displayName || model.name)" @click="launch(model)">{{ starting === model.name ? '正在确认…' : model.ready ? modelEntry(model).label : '暂未接入' }}<ClientIcon name="arrow" /></button><button type="button" class="qm-compare-remove" @click="toggleCompare(model)">移出对照</button></article></div><p v-if="startError" class="qm-inline-error" role="alert">{{ startError }}</p></dialog>
  </section>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { ElMessage } from 'element-plus';
import { api } from '../../api/client.js';
import { useAuth } from '../../stores/auth.js';
import { capabilityLabel, contextLabel, contextSize, exactTokens, imageOnly, matchesModel, microsLabel, modelBilling, modelCaps, modelEntry, modelVendor } from '../../lib/model-presentation.js';
import ClientIcon from '../reference/ClientIcon.vue';
import BrandLoader from './BrandLoader.vue';
import './model-discovery.css';
const auth = useAuth(), router = useRouter();
const models = ref([]), loading = ref(true), loadError = ref(''), keyword = ref(''), capability = ref(''), vendor = ref(''), readyOnly = ref(false), sort = ref('default'), limit = ref(9), starting = ref(''), startError = ref('');
const selectedNames = ref([]), detailName = ref(''), detailDialog = ref(null), compareDialog = ref(null), compareOpener = ref(null), compareOpen = ref(false);
const snapshots = new Map(), controllers = new Map();
let active = true, owner = auth.user?.id, detailOpener = null;
const current = () => active && !!owner && owner === auth.user?.id;
function scope(key) { controllers.get(key)?.abort(); const controller = new AbortController(); controllers.set(key, controller); const user = owner; return { signal: controller.signal, current: () => current() && user === owner && !controller.signal.aborted && controllers.get(key) === controller }; }
const capabilities = [{ key: '', label: '全部能力', icon: 'model' }, { key: 'chat', label: '文字对话', icon: 'chat' }, { key: 'reasoning', label: '深度思考', icon: 'reasoning' }, { key: 'vision', label: '图片理解', icon: 'image' }, { key: 'image', label: '图像创作', icon: 'palette' }, { key: 'long', label: '128K+ 上下文', icon: 'file' }];
const readyCount = computed(() => models.value.filter(model => model.ready).length);
const vendors = computed(() => { const map = new Map(); for (const model of models.value) { const key = modelVendor(model); map.set(key, (map.get(key) || 0) + 1); } return [...map].map(([name, count]) => ({ name, count })); });
const filtered = computed(() => { const rows = models.value.filter(model => matchesModel(model, keyword.value, capability.value, readyOnly.value, vendor.value)); return sort.value === 'context' ? rows.sort((a, b) => contextSize(b.maxContext) - contextSize(a.maxContext)) : sort.value === 'name' ? rows.sort((a, b) => String(a.displayName || a.name).localeCompare(String(b.displayName || b.name), 'zh-CN')) : rows; });
const visibleModels = computed(() => filtered.value.slice(0, limit.value));
const selectedModels = computed(() => selectedNames.value.map(name => modelFor(name)).filter(Boolean));
const detailModel = computed(() => detailName.value ? modelFor(detailName.value) : null);
function modelFor(name) { return models.value.find(model => model.name === name) || (snapshots.has(name) ? { ...snapshots.get(name), ready: false, unavailable: true } : null); }
function iconFor(model) { const caps = modelCaps(model); return imageOnly(model) ? 'palette' : caps.includes('reasoning') ? 'reasoning' : caps.includes('vision') ? 'image' : caps.includes('tools') ? 'settings' : 'chat'; }
function remember(rows) { for (const model of rows) if (selectedNames.value.includes(model.name) || detailName.value === model.name) snapshots.set(model.name, model); }
async function loadCatalog() { const req = scope('catalog'); loading.value = true; loadError.value = ''; try { const data = await api.get('/models/plaza', { signal: req.signal }); if (!req.current()) return; models.value = Array.isArray(data.models) ? data.models : []; remember(models.value); } catch (error) { if (req.current()) loadError.value = error.message || '模型列表暂未加载，请重试。'; } finally { if (req.current()) loading.value = false; } }
function resetFilters() { keyword.value = ''; capability.value = ''; vendor.value = ''; readyOnly.value = false; }
function toggleCompare(model) { const index = selectedNames.value.indexOf(model.name); if (index >= 0) { selectedNames.value = selectedNames.value.filter(name => name !== model.name); if (compareOpen.value && selectedNames.value.length < 2) closeCompare(); return; } if (selectedNames.value.length >= 3) return ElMessage.info('一次最多对照 3 个模型，先移出一位，再认识新的搭档。'); snapshots.set(model.name, model); selectedNames.value = [...selectedNames.value, model.name]; }
async function openDetail(model, event) { snapshots.set(model.name, model); detailName.value = model.name; startError.value = ''; detailOpener = event?.currentTarget || null; await nextTick(); if (current() && detailName.value === model.name && !detailDialog.value.open) detailDialog.value.showModal(); }
function closeDetail(restore = true) { if (restore && starting.value) { controllers.get('start')?.abort(); starting.value = ''; } if (detailDialog.value?.open) detailDialog.value.close(); detailName.value = ''; const target = detailOpener; detailOpener = null; if (restore && target?.isConnected) target.focus({ preventScroll: true }); }
function onDetailClosed() { if (!detailDialog.value?.open && detailName.value) closeDetail(); }
function openCompare() { startError.value = ''; compareOpen.value = true; if (!compareDialog.value.open) compareDialog.value.showModal(); }
function closeCompare(restore = true) { if (restore && starting.value) { controllers.get('start')?.abort(); starting.value = ''; } if (compareDialog.value?.open) compareDialog.value.close(); compareOpen.value = false; const target = compareOpener.value?.disabled ? document.querySelector('.qm-tray-clear') : compareOpener.value; if (restore && target?.isConnected) target.focus({ preventScroll: true }); }
function onCompareClosed() { if (!compareDialog.value?.open && compareOpen.value) closeCompare(); }
function onBackdrop(event, kind) { const dialog = kind === 'detail' ? detailDialog.value : compareDialog.value; if (event.target !== dialog) return; const rect = dialog.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) kind === 'detail' ? closeDetail() : closeCompare(); }
async function launch(model) { if (!current() || starting.value || !model.ready) return; controllers.get('catalog')?.abort(); loading.value = false; const req = scope('start'); starting.value = model.name; startError.value = ''; try { const rows = await api.get('/models/available', { signal: req.signal }); if (!req.current()) return; models.value = Array.isArray(rows) ? rows : []; remember(models.value); const latest = models.value.find(row => row.name === model.name); if (!latest?.ready) { startError.value = '这位模型搭档暂时无法使用，请刷新或换一位。'; return; } closeDetail(false); closeCompare(false); await router.push({ path: modelEntry(latest).path, query: { model: latest.name } }); } catch (error) { if (req.current()) startError.value = error.message || '暂时无法确认模型状态，请再试一次。'; } finally { if (req.current()) starting.value = ''; } }
watch([keyword, capability, vendor, readyOnly, sort], () => { limit.value = 9; });
function clear() { for (const controller of controllers.values()) controller.abort(); controllers.clear(); starting.value = ''; startError.value = ''; loadError.value = ''; loading.value = true; models.value = []; selectedNames.value = []; snapshots.clear(); closeDetail(false); closeCompare(false); }
watch(() => auth.user?.id, id => { if (id === owner) return; clear(); owner = id; if (id) void loadCatalog(); });
onMounted(loadCatalog);
onBeforeUnmount(() => { active = false; clear(); });
</script>
